);
INSERT INTO booking_pass_plans_new ("id","line_account_id","kind","name","price","count","monthly_limit","valid_days","target_scope_json","allow_without_pass","status","version","created_by","created_at","idempotency_key","request_json","notify_remaining_one","notify_expiry_14_days","event_target_scope_json") SELECT "id","line_account_id","kind","name","price","count","monthly_limit","valid_days","target_scope_json","allow_without_pass","status","version","created_by","created_at","idempotency_key","request_json","notify_remaining_one","notify_expiry_14_days","event_target_scope_json" FROM booking_pass_plans;
